    logger = logging.getLogger(__name__)

    # Reads one splayed partition directly. Loading the whole HDB would also run
    # any q scripts stored in the HDB root.
    _SPLAYED_META_Q = "{[p] m:0!meta get hsym p; (string m`c; m`t)}"

    # The framework record parser has no ShortType, so bytes and shorts widen to int.
    Q_META_TYPE_TO_SPARK = {
        "b": "BooleanType",
        "x": "IntegerType",
        "h": "IntegerType",
        "i": "IntegerType",
        "j": "LongType",
        "e": "FloatType",
        "f": "DoubleType",
        "c": "StringType",
        "s": "StringType",
        "p": "TimestampType",
        "d": "StringType",
        "z": "TimestampType",
        "n": "LongType",
        "u": "StringType",
        "v": "StringType",
        "t": "StringType",
        "g": "StringType",
        "C": "StringType",
    }


    def _dedupe_column_defs(columns: List[dict]) -> List[dict]:
        """Return column definitions with unique case-insensitive names."""
        deduped: List[dict] = []
        seen = set()
        for column in columns:
            name = str(column.get("name", "")).strip()
            if not name:
                continue
            lowered = name.lower()
            if lowered in seen:
                logger.warning("Dropping duplicate inferred column: %s", name)
                continue
            seen.add(lowered)
            column_def = {"name": name, "spark_type": str(column.get("spark_type", "StringType"))}
            if column.get("q_type") is not None:
                column_def["q_type"] = column["q_type"]
            deduped.append(column_def)
        return deduped


    def _clean_type_char(type_char) -> str:
        value = type_char
        if isinstance(value, (bytes, bytearray)):
            value = value.decode("latin1", "ignore")
        text = str(value or "").strip().strip("`").strip()
        if (
            len(text) >= 3
            and text[0] in {"b", "B"}
            and text[1] in {"'", '"'}
            and text[-1] in {"'", '"'}
        ):
            text = text[2:-1]
        text = text.strip().strip("'").strip('"').strip()
        return text[-1] if text else ""


    def _map_meta_type_char(type_char) -> str:
        return Q_META_TYPE_TO_SPARK.get(_clean_type_char(type_char), "StringType")


    def infer_schema_from_partition(
        hdb_root_path: str,
        kdb_table_name: str,
        date_partition: str,
        runtime_config: PyKxRuntimeConfig,
    ) -> List[dict]:
        """Infer column definitions from one splayed KDB date partition."""
        table_path = hdb_child_path(hdb_root_path, date_partition, kdb_table_name)
        if scan_partition_table(hdb_root_path, date_partition, kdb_table_name) is None:
            raise RuntimeError(f"Could not infer schema for {kdb_table_name}: {table_path} is missing")
        kx = prepare_pykx(runtime_config)
        try:
            _ensure_sym_domain(kx, hdb_root_path)
            meta = kx.q(_SPLAYED_META_Q, f"{table_path}/")
        except Exception as exc:
            raise RuntimeError(
                f"Could not infer schema for {kdb_table_name} from {table_path}: "
                f"{type(exc).__name__}: {exc}"
            ) from exc

        return _with_date_column(_meta_columns(meta))


    def _meta_columns(meta) -> List[dict]:
        value = to_python(meta)
        try:
            raw_names, raw_types = value
        except (TypeError, ValueError):
            raise RuntimeError("KDB meta returned an unexpected shape.") from None

        names = [_text(item) for item in to_python(raw_names)]
        types = _type_chars(to_python(raw_types))
        if len(names) != len(types):
            raise RuntimeError(
                f"KDB meta returned {len(names)} column names and {len(types)} type codes."
            )
        return [
            {
                "name": validate_hdb_name(name, "column name"),
                "spark_type": _map_meta_type_char(type_char),
                "q_type": _clean_type_char(type_char),
            }
            for name, type_char in zip(names, types)
        ]


    def _text(value) -> str:
        if isinstance(value, (bytes, bytearray)):
            return value.decode("utf-8")
        return str(value)


    def _type_chars(value) -> list[str]:
        if isinstance(value, (bytes, bytearray)):
            return list(value.decode("latin1"))
        if isinstance(value, str):
            return list(value)
        return [_text(item) for item in value]


    def _with_date_column(columns: List[dict]) -> List[dict]:
        has_date = any(str(column.get("name", "")).strip().lower() == "date" for column in columns)
        result = []
        if not has_date:
            result.append({"name": "date", "spark_type": "StringType"})
        result.extend(columns)
        return _dedupe_column_defs(result)


    def columns_to_spark_schema(columns: List[dict]):
        """Convert a list of column definitions to a StructType."""
        from pyspark.sql.types import (
            BooleanType,
            DoubleType,
            FloatType,
            IntegerType,
            LongType,
            StringType,
            StructField,
            StructType,
            TimestampType,
        )

        type_map = {
            "BooleanType": BooleanType(),
            "IntegerType": IntegerType(),
            "LongType": LongType(),
            "FloatType": FloatType(),
            "DoubleType": DoubleType(),
            "StringType": StringType(),
            "TimestampType": TimestampType(),
        }

        fields = []
        for column in _dedupe_column_defs(columns):
            fields.append(
                StructField(
                    column["name"],
                    type_map.get(column["spark_type"], StringType()),
                    nullable=True,
                )
            )
        return StructType(fields)


    ########################################################
    # src/databricks/labs/community_connector/sources/kx_kdb/kx_kdb.py
    ########################################################

    logger = logging.getLogger(__name__)

    DEFAULT_MAX_DATES_PER_BATCH = 250
    DEFAULT_MAX_TASKS_PER_BATCH = 2000
    DEFAULT_MAX_ROWS_PER_TASK = 2_000_000
    _REMOVED_TABLE_OPTIONS = ("partition_strategy", "sym_column")


    class KxKdbLakeflowConnect(LakeflowConnect, SupportsPartitionedStream):
        """Read immutable KDB HDB date partitions through the Lakeflow connector APIs.

        On managed ingestion, pipeline table configuration is merged into
        ``options`` and can fill connection keys that the connection leaves unset;
        the connector cannot tell where a key came from. Keys set on the connection
        take precedence, and the two required paths are always set there. KDB-X
        setup therefore reads only files inside the Unity Catalog Volume of
        ``license_volume_path`` and rejects the removed bootstrap keys (see
        ``build_runtime_config``). Table options are the keys in
        ``external_options_allowlist``.
        """

        def __init__(self, options: dict[str, str]) -> None:
            super().__init__(options)
            self.hdb_root_path = self._required_absolute_path_option("hdb_root_path")
            self._required_absolute_path_option("license_volume_path")
            # The runtime config is built on the driver and travels with the
            # serialized connector object to executors.
            self.runtime_config = build_runtime_config(self.options)
            self.discovery_sample_dates = self._int_option("discovery_sample_dates", 0)
            self._schema_cache: dict[tuple[str, str], StructType] = {}
            self._column_cache: dict[tuple[str, str], list[dict]] = {}
            self._table_dir_cache: dict[str, str] = {}
            self._shape_cache: dict[tuple[str, str], PartitionShape] = {}

        def list_tables(self) -> list[str]:
            return discover_tables(self.hdb_root_path, self.discovery_sample_dates)

        def get_table_schema(self, table_name: str, table_options: dict[str, str]) -> StructType:
            self._validate_table_options(table_options)
            cache_key = (table_name.lower(), self._ingestion_mode(table_options))
            if cache_key not in self._schema_cache:
                self._schema_cache[cache_key] = columns_to_spark_schema(
                    self._column_defs(table_name, table_options)
                )
            return self._schema_cache[cache_key]

        def read_table_metadata(self, table_name: str, table_options: dict[str, str]) -> dict:
            self._actual_table_name(table_name)
            self._validate_table_options(table_options)
            return {"primary_keys": None, "cursor_field": None, "ingestion_type": "append"}

        def read_table(
            self,
            table_name: str,
            start_offset: dict | None,
            table_options: dict[str, str],
        ) -> tuple[Iterator[dict], dict | None]:
            if start_offset is None:
                # A batch read, not a micro-batch: read every complete date.
                partitions = self.get_partitions(table_name, table_options)
                end_offset = {"date_partition": partitions[-1]["date_partition"]} if partitions else {}
            else:
                end_offset = self.latest_offset(table_name, table_options, start_offset)
                if end_offset == start_offset:
                    return iter(()), start_offset
                partitions = self.get_partitions(table_name, table_options, start_offset, end_offset)
            records = chain.from_iterable(
                self.read_partition(table_name, partition, table_options) for partition in partitions
            )
            return records, end_offset

        def latest_offset(
            self,
            table_name: str,
            table_options: dict[str, str],
            start_offset: dict | None = None,
        ) -> dict:
            admitted = self._admitted_partitions(table_name, table_options, start_offset, capped=True)
            if not admitted:
                return dict(start_offset or {})
            return {"date_partition": admitted[-1]}

        def get_partitions(
            self,
            table_name: str,
            table_options: dict[str, str],
            start_offset: dict | None = None,
            end_offset: dict | None = None,
        ) -> Sequence[dict]:
            if start_offset is None and end_offset is None:
                selected = self._admitted_partitions(table_name, table_options, None, capped=False)
            else:
                self._validate_table_options(table_options)
                end_partition = normalize_partition_date((end_offset or {}).get("date_partition"))
                if not end_partition:
                    return []
                start_partition = normalize_partition_date((start_offset or {}).get("date_partition"))
                selected = [
                    partition
                    for partition in self._available_partitions(table_name, table_options)
                    if (start_partition is None or partition > start_partition)
                    and partition <= end_partition
                ]
            if not selected:
                return []

            max_rows = self._max_rows_per_task(table_options)
            min_age = self._min_partition_age_seconds(table_options)
            newest = latest_table_partition(self.hdb_root_path, table_name)
            descriptors: list[dict] = []
            total_rows = 0
            for partition in selected:
                shape = self._partition_shape(table_name, partition, newest, min_age)
                if not shape.complete:
                    raise RuntimeError(
                        f"KX KDB table {table_name!r} date {partition} is in this batch but "
                        f"is no longer complete: {shape.reason}."
                    )
                descriptors.extend(_row_ranges(partition, shape.row_count, max_rows))
                total_rows += shape.row_count
            logger.info(
                "KX KDB partition plan table=%s dates=%s first=%s last=%s rows=%s tasks=%s",
                table_name,
                len(selected),
                selected[0],
                selected[-1],
                total_rows,
                len(descriptors),
            )
            return descriptors

        def read_partition(
            self,
            table_name: str,
            partition: dict,
            table_options: dict[str, str],
        ) -> Iterator[dict]:
            date_partition = normalize_partition_date(partition.get("date_partition"))
            if not date_partition:
                return iter(())
            self._validate_table_options(table_options)
            try:
                row_offset = int(partition["row_offset"])
                row_count = int(partition["row_count"])
                total_rows = int(partition["total_rows"])
            except (KeyError, TypeError, ValueError):
                raise ValueError(
                    "KX KDB partition descriptors must contain integer 'row_offset', "
                    "'row_count', and 'total_rows'."
                ) from None
            return read_kdb_row_range(
                hdb_root_path=self.hdb_root_path,
                kdb_table_name=self._actual_table_name(table_name),
                date_partition=date_partition,
                row_offset=row_offset,
                row_count=row_count,
                total_rows=total_rows,
                runtime_config=self.runtime_config,
                column_defs=self._column_defs(table_name, table_options),
            )

        def _admitted_partitions(
            self,
            table_name: str,
            table_options: dict[str, str],
            start_offset: dict | None,
            *,
            capped: bool,
        ) -> list[str]:
            """Return the complete dates after ``start_offset``, in order.

            Admission stops before the table's newest date while that date is
            still being written, and before any date changed within
            ``min_partition_age_minutes``. It fails on any other incomplete date,
            so the offset never moves past a date that has not been read. With
            ``capped``, admission also stops at ``max_dates_per_batch`` dates or
            ``max_tasks_per_batch`` tasks; the first date is always admitted.
            """
            self._validate_table_options(table_options)
            start_partition = normalize_partition_date((start_offset or {}).get("date_partition"))
            candidates = [
                partition
                for partition in self._available_partitions(table_name, table_options)
                if start_partition is None or partition > start_partition
            ]
            if not candidates:
                return []

            newest = latest_table_partition(self.hdb_root_path, table_name)
            max_dates = self._positive_int_option(
                table_options, "max_dates_per_batch", DEFAULT_MAX_DATES_PER_BATCH
            )
            max_tasks = self._positive_int_option(
                table_options, "max_tasks_per_batch", DEFAULT_MAX_TASKS_PER_BATCH
            )
            max_rows = self._max_rows_per_task(table_options)
            min_age = self._min_partition_age_seconds(table_options)

            admitted: list[str] = []
            tasks = 0
            for partition in candidates:
                if capped and len(admitted) >= max_dates:
                    break
                shape = self._partition_shape(table_name, partition, newest, min_age)
                if not shape.complete:
                    if partition == newest or shape.recent:
                        logger.info(
                            "KX KDB table=%s is waiting for date %s to finish writing: %s",
                            table_name,
                            partition,
                            shape.reason,
                        )
                        break
                    raise RuntimeError(
                        f"KX KDB table {table_name!r} date {partition} is incomplete: "
                        f"{shape.reason}. Only the newest date of a table may still be "
                        "in progress. Repair the partition, or set start_date after it."
                    )
                date_tasks = math.ceil(shape.row_count / max_rows)
                if capped and admitted and tasks + date_tasks > max_tasks:
                    break
                admitted.append(partition)
                tasks += date_tasks

            if capped and tasks > max_tasks:
                logger.warning(
                    "KX KDB table=%s date %s alone needs %s tasks, more than "
                    "max_tasks_per_batch=%s; raise max_rows_per_task to reduce it.",
                    table_name,
                    admitted[0],
                    tasks,
                    max_tasks,
                )
            if admitted:
                logger.info(
                    "KX KDB admission table=%s start=%s dates=%s first=%s last=%s tasks=%s",
                    table_name,
                    start_partition,
                    len(admitted),
                    admitted[0],
                    admitted[-1],
                    tasks,
                )
            return admitted

        def _partition_shape(
            self,
            table_name: str,
            date_partition: str,
            newest: str,
            min_age_seconds: float,
        ) -> PartitionShape:
            cache_key = (table_name.lower(), date_partition)
            cached = self._shape_cache.get(cache_key)
            if cached is not None:
                return cached
            is_newest = date_partition == newest
            shape = read_partition_shape(
                hdb_root_path=self.hdb_root_path,
                kdb_table_name=self._actual_table_name(table_name),
                date_partition=date_partition,
                runtime_config=self.runtime_config,
                check_all_columns=is_newest,
                min_age_seconds=min_age_seconds,
            )
            # Older complete dates are immutable. The newest date may still be
            # written, and a sparse date's table directory may still appear, so
            # both are checked again each time.
            if shape.complete and shape.present and not is_newest:
                self._shape_cache[cache_key] = shape
            return shape

        def _required_option(self, key: str) -> str:
            value = str(self.options.get(key, "")).strip()
            if not value:
                raise ValueError(f"KX KDB connector requires {key!r} in connection options")
            return value

        def _required_absolute_path_option(self, key: str) -> str:
            value = self._required_option(key)
            if not Path(value).is_absolute():
                raise ValueError(f"KX KDB connector requires {key!r} to be an absolute filesystem path")
            return value

        def _int_option(self, key: str, default: int) -> int:
            value = str(self.options.get(key, "")).strip()
            if not value:
                return default
            return int(value)

        @staticmethod
        def _positive_int_option(table_options: dict[str, str], key: str, default: int) -> int:
            raw = str(table_options.get(key, "")).strip()
            if not raw:
                return default
            try:
                value = int(raw)
            except ValueError:
                raise ValueError(f"{key} must be a positive integer, got {raw!r}") from None
            if value <= 0:
                raise ValueError(f"{key} must be a positive integer, got {raw!r}")
            return value

        def _max_rows_per_task(self, table_options: dict[str, str]) -> int:
            return self._positive_int_option(
                table_options, "max_rows_per_task", DEFAULT_MAX_ROWS_PER_TASK
            )

        @staticmethod
        def _min_partition_age_seconds(table_options: dict[str, str]) -> float:
            raw = str(table_options.get("min_partition_age_minutes", "")).strip()
            if not raw:
                return 0.0
            try:
                minutes = float(raw)
            except ValueError:
                minutes = -1.0
            if not math.isfinite(minutes) or minutes < 0:
                raise ValueError(
                    f"min_partition_age_minutes must be a non-negative number, got {raw!r}"
                )
            return minutes * 60

        def _validate_table_options(self, table_options: dict[str, str]) -> None:
            removed = [key for key in _REMOVED_TABLE_OPTIONS if key in table_options]
            if removed:
                raise ValueError(
                    f"KX KDB table options {removed} are no longer supported. Each date is "
                    "split into row ranges; use max_rows_per_task to size them."
                )
            self._ingestion_mode(table_options)

        def _ingestion_mode(self, table_options: dict[str, str]) -> str:
            mode = str(table_options.get("ingestion_mode", "append")).strip().lower()
            if mode != "append":
                raise ValueError(f"Unsupported ingestion_mode {mode!r}. KX KDB supports append only.")
            return mode

        def _actual_table_name(self, table_name: str) -> str:
            cache_key = table_name.lower()
            if cache_key not in self._table_dir_cache:
                self._table_dir_cache[cache_key] = resolve_table_directory_name(
                    self.hdb_root_path, table_name
                )
            return self._table_dir_cache[cache_key]

        def _available_partitions(self, table_name: str, table_options: dict[str, str]) -> list[str]:
            # Discovery results are cached per process with a bounded TTL, so a
            # long-lived stream reader still sees new date partitions.
            return discover_table_partitions(
                root_path=self.hdb_root_path,
                table_name=table_name,
                start_date=normalize_partition_date(table_options.get("start_date")),
                end_date=normalize_partition_date(table_options.get("end_date")),
            )

        def _column_defs(self, table_name: str, table_options: dict[str, str]) -> list[dict]:
            cache_key = (table_name.lower(), self._ingestion_mode(table_options))
            if cache_key in self._column_cache:
                return self._column_cache[cache_key]

            partitions = self._available_partitions(table_name, table_options)
            if not partitions:
                raise RuntimeError(
                    f"No partitions found for table {table_name!r} under {self.hdb_root_path}"
                )

            actual_table_name = self._actual_table_name(table_name)
            # Interior dates of a sparse table may not contain the table directory.
            schema_partition = next(
                (
                    partition
                    for partition in partitions
                    if table_partition_exists(self.hdb_root_path, partition, actual_table_name)
                ),
                partitions[0],
            )
            columns = infer_schema_from_partition(
                hdb_root_path=self.hdb_root_path,
                kdb_table_name=actual_table_name,
                date_partition=schema_partition,
                runtime_config=self.runtime_config,
            )

            self._column_cache[cache_key] = columns
            return columns


    def _row_ranges(date_partition: str, total_rows: int, max_rows_per_task: int) -> list[dict]:
        return [
            {
                "date_partition": date_partition,
                "row_offset": row_offset,
                "row_count": min(max_rows_per_task, total_rows - row_offset),
                "total_rows": total_rows,
            }
            for row_offset in range(0, total_rows, max_rows_per_task)
        ]


    ########################################################
    # src/databricks/labs/community_connector/sparkpds/lakeflow_datasource.py
    ########################################################

    LakeflowConnectImpl = KxKdbLakeflowConnect
    # Constant option or column names
    METADATA_TABLE = "_community_table_metadata"
    NAMESPACES_TABLE = "_community_namespaces"
    TABLES_TABLE = "_community_tables"
    VIRTUAL_TABLES = (METADATA_TABLE, NAMESPACES_TABLE, TABLES_TABLE)
    TABLE_NAME = "tableName"
    TABLE_NAME_LIST = "tableNameList"
    TABLE_CONFIGS = "tableConfigs"
    IS_DELETE_FLOW = "isDeleteFlow"
    NAMESPACE_PREFIX = "namespacePrefix"
    NAMESPACE = "namespace"


    def _decode_list_of_str_option(option_name: str, value: str | None) -> list[str] | None:
        """Decode and validate a JSON-encoded ``list[str]`` Spark option.

        Returns ``None`` if the option is absent; otherwise the parsed list.
        Raises ``ValueError`` with the offending value if the JSON is malformed
        or the decoded value is not a list of strings.
        """
        if value is None:
            return None
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError as e:
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded list[str]; "
                f"got non-JSON value: {value!r}"
            ) from e
        if not isinstance(decoded, list) or not all(isinstance(s, str) for s in decoded):
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded list[str]; "
                f"got: {decoded!r}"
            )
        return decoded


    def _decode_dict_option(option_name: str, value: str | None) -> dict:
        """Decode and validate a JSON-encoded ``dict`` Spark option."""
        if value is None:
            return {}
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError as e:
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded dict; "
                f"got non-JSON value: {value!r}"
            ) from e
        if not isinstance(decoded, dict):
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded dict; got: {decoded!r}"
            )
        return decoded


    # PySpark's DataSource API requires camelCase method names and inherits
    # semantics from the parent class, so per-method docstrings are redundant.
    # pylint: disable=invalid-name,missing-function-docstring
    class LakeflowStreamReader(SimpleDataSourceStreamReader, SupportsTriggerAvailableNow):
        """
        Implements a data source stream reader for Lakeflow Connect.
        Currently, only the simpleStreamReader is implemented, which uses a
        more generic protocol suitable for most data sources that support
        incremental loading.
        """

        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.lakeflow_connect = lakeflow_connect
            self.schema = schema

        def initialOffset(self):
            return {}

        def read(self, start: dict) -> (Iterator[tuple], dict):
            is_delete_flow = self.options.get(IS_DELETE_FLOW) == "true"
            # Strip delete flow options before passing to connector
            table_options = {
                k: v for k, v in self.options.items() if k != IS_DELETE_FLOW
            }

            if is_delete_flow:
                records, offset = self.lakeflow_connect.read_table_deletes(
                    self.options[TABLE_NAME], start, table_options
                )
            else:
                records, offset = self.lakeflow_connect.read_table(
                    self.options[TABLE_NAME], start, table_options
                )
            rows = map(lambda x: parse_value(x, self.schema), records)
            return rows, offset

        def readBetweenOffsets(self, start: dict, end: dict) -> Iterator[tuple]:
            # TODO: This does not ensure the records returned are identical across repeated calls.
            # For append-only tables, the data source must guarantee that reading from the same
            # start offset will always yield the same set of records.
            # For tables ingested as incremental CDC, it is only necessary that no new changes
            # are missed in the returned records.
            return self.read(start)[0]

        def prepareForTriggerAvailableNow(self) -> None:
            # No need to do anything special here. Everything is handled in the __init__ method.
            pass


    class LakeflowPartitionedStreamReader(DataSourceStreamReader, SupportsTriggerAvailableNow):
        """Proxy that bridges SupportsPartitionedStream to PySpark's DataSourceStreamReader.

        Used when a connector implements the SupportsPartitionedStream mixin to
        support partitioned streaming reads across Spark executors.
        """

        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.schema = schema
            self.lakeflow_connect = lakeflow_connect
            self.table_name = options[TABLE_NAME]
            self.table_options = {k: v for k, v in options.items() if k != IS_DELETE_FLOW}

        def initialOffset(self):
            return {}

        def getDefaultReadLimit(self):
            # Admission control is the connector's responsibility (e.g. via
            # window_days, max_records_per_batch), not the engine's.  Always
            # ask the engine for ReadAllAvailable.
            return ReadAllAvailable()

        def latestOffset(self, start: dict, limit) -> dict:
            # We declared ReadAllAvailable via getDefaultReadLimit; the engine
            # must respect it.  Anything else means admission-control expectations
            # we do not support — fail loudly rather than silently ignore.
            if not isinstance(limit, ReadAllAvailable):
                raise ValueError(
                    f"LakeflowPartitionedStreamReader only supports ReadAllAvailable; "
                    f"got {type(limit).__name__}. Micro-batch sizing must be controlled "
                    f"by the connector implementation (table_options), not the engine."
                )
            return self.lakeflow_connect.latest_offset(
                self.table_name, self.table_options, start
            )

        def partitions(self, start: dict, end: dict):
            partition_descs = self.lakeflow_connect.get_partitions(
                self.table_name, self.table_options, start, end
            )
            return [InputPartition(json.dumps(p)) for p in partition_descs]

        def read(self, partition: InputPartition):
            partition_desc = json.loads(partition.value)
            records = self.lakeflow_connect.read_partition(
                self.table_name, partition_desc, self.table_options
            )
            return map(lambda x: parse_value(x, self.schema), records)

        def prepareForTriggerAvailableNow(self) -> None:
            # No need to do anything special here. Everything is handled in the __init__ method.
            pass


    class LakeflowBatchReader(DataSourceReader):
        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.schema = schema
            self.lakeflow_connect = lakeflow_connect
            self.table_name = options[TABLE_NAME]
            self._supports_partition = isinstance(lakeflow_connect, SupportsPartition)

        def partitions(self):
            if self._supports_partition and self.table_name not in VIRTUAL_TABLES:
                try:
                    partition_descs = self.lakeflow_connect.get_partitions(
                        self.table_name, self.options
                    )
                    return [InputPartition(json.dumps(p)) for p in partition_descs]
                except Exception:
                    self._supports_partition = False
            return [InputPartition(None)]

        def read(self, partition):
            if self.table_name == METADATA_TABLE:
                records = self._read_table_metadata()
            elif self.table_name == NAMESPACES_TABLE:
                records = self._read_namespaces()
            elif self.table_name == TABLES_TABLE:
                records = self._read_tables()
            elif self._supports_partition and partition.value is not None:
                partition_desc = json.loads(partition.value)
                records = self.lakeflow_connect.read_partition(
                    self.table_name, partition_desc, self.options
                )
            else:
                records, _ = self.lakeflow_connect.read_table(self.table_name, None, self.options)
            return map(lambda x: parse_value(x, self.schema), records)

        def _read_table_metadata(self):
            table_names = _decode_list_of_str_option(
                TABLE_NAME_LIST, self.options.get(TABLE_NAME_LIST)
            ) or []
            table_configs = _decode_dict_option(
                TABLE_CONFIGS, self.options.get(TABLE_CONFIGS)
            )
            all_records = []
            # Preserve caller-supplied table order — caller controls it.
            for table in table_names:
                metadata = self.lakeflow_connect.read_table_metadata(
                    table, table_configs.get(table, {})
                )
                all_records.append({TABLE_NAME: table, **metadata})
            return all_records

        def _read_namespaces(self):
            # Connectors without SupportsNamespaces are flat — no rows.
            if not isinstance(self.lakeflow_connect, SupportsNamespaces):
                return []
            prefix = _decode_list_of_str_option(
                NAMESPACE_PREFIX, self.options.get(NAMESPACE_PREFIX)
            )
            namespaces = self.lakeflow_connect.list_namespaces(prefix)
            # Sort framework-side for deterministic output regardless of
            # connector iteration order.
            return [{"namespace": ns} for ns in sorted(namespaces)]

        def _read_tables(self):
            namespace_supplied = NAMESPACE in self.options
            if isinstance(self.lakeflow_connect, SupportsNamespaces):
                if not namespace_supplied:
                    raise ValueError(
                        f"option '{NAMESPACE}' is required when reading "
                        f"'{TABLES_TABLE}' against a connector that implements "
                        f"SupportsNamespaces. Pass a JSON-encoded list[str] "
                        f"(use '[]' for root-level tables; walk the tree via "
                        f"'{NAMESPACES_TABLE}' to enumerate every namespace)."
                    )
                namespace = _decode_list_of_str_option(
                    NAMESPACE, self.options[NAMESPACE]
                )
                tables = self.lakeflow_connect.list_tables_in_namespace(namespace)
                return [
                    {"namespace": namespace, TABLE_NAME: tn}
                    for tn in sorted(tables)
                ]
            # Flat connector path. Reject a stray `namespace` option — the
            # caller probably mistook this connector for namespace-aware and
            # silently ignoring the option would mask the bug.
            if namespace_supplied:
                raise ValueError(
                    f"option '{NAMESPACE}' was supplied but the connector does "
                    f"not implement SupportsNamespaces. Either omit the option "
                    f"or use a namespace-aware connector."
                )
            return [
                {"namespace": [], TABLE_NAME: tn}
                for tn in sorted(self.lakeflow_connect.list_tables())
            ]


    class LakeflowSource(DataSource):
        """
        PySpark DataSource base for Lakeflow Connect.

        Two ways the connector implementation is bound:

        - Per-source subclass (wheel / multi-file deployment): subclass and set
          ``_lakeflow_connect_cls``::

              class GmailDataSource(LakeflowSource):
                  _lakeflow_connect_cls = GmailLakeflowConnect

              spark.dataSource.register(GmailDataSource)

        - Merged single-file deployment (SDP): ``_lakeflow_connect_cls`` is left
          ``None`` and the connector is taken from the module-level
          ``LakeflowConnectImpl`` placeholder, which the merge script substitutes
          with the actual implementation class.
        """

        # Per-source subclasses set this. Left ``None`` on the base so the merged
        # single-file path falls back to the ``LakeflowConnectImpl`` placeholder.
        _lakeflow_connect_cls = None

        # Spark format name. Defaults to "lakeflow_connect" because Unity Catalog
        # connection-option injection looks for that exact string. A per-source
        # subclass may override this with its source name once it no longer relies
        # on UC injection (see the commented override in each source's __init__.py).
        _format_name = "lakeflow_connect"

        def __init__(self, options):
            self.options = options
            table = options.get(TABLE_NAME)
            # Catch typos against the framework's reserved virtual-table namespace
            # early — falling through to the connector with an unknown
            # `_community_*` name yields a confusing per-connector error.
            if table and table.startswith("_community_") and table not in VIRTUAL_TABLES:
                raise ValueError(
                    f"unknown framework virtual table '{table}'. Valid framework "
                    f"virtual tables are: {', '.join(VIRTUAL_TABLES)}. "
                    f"For a regular source table, use a name that does not start "
                    f"with '_community_'."
                )
            # Per-source subclasses bind the implementation via _lakeflow_connect_cls.
            # The merged single-file path leaves it None and relies on the
            # LakeflowConnectImpl placeholder (substituted by the merge script).
            connect_cls = type(self)._lakeflow_connect_cls or LakeflowConnectImpl
            self.lakeflow_connect = connect_cls(options)  # pylint: disable=abstract-class-instantiated

        @classmethod
        def name(cls):
            return cls._format_name

        def schema(self):
            table = self.options[TABLE_NAME]
            if table == METADATA_TABLE:
                return StructType(
                    [
                        StructField(TABLE_NAME, StringType(), False),
                        StructField("primary_keys", ArrayType(StringType()), True),
                        StructField("cursor_field", StringType(), True),
                        StructField("ingestion_type", StringType(), True),
                    ]
                )
            if table == NAMESPACES_TABLE:
                return StructType(
                    [
                        StructField("namespace", ArrayType(StringType()), False),
                    ]
                )
            if table == TABLES_TABLE:
                return StructType(
                    [
                        StructField("namespace", ArrayType(StringType()), False),
                        StructField(TABLE_NAME, StringType(), False),
                    ]
                )
            return self.lakeflow_connect.get_table_schema(table, self.options)

        def reader(self, schema: StructType):
            return LakeflowBatchReader(self.options, schema, self.lakeflow_connect)

        def streamReader(self, schema: StructType):
            # Use the partitioned DataSourceStreamReader when the connector
            # implements SupportsPartitionedStream and the table opts in.
            # Otherwise, delegate to super() which raises PySparkNotImplementedError,
            # causing Spark to fall back to simpleStreamReader().
            if isinstance(self.lakeflow_connect, SupportsPartitionedStream):
                table = self.options[TABLE_NAME]
                if self.lakeflow_connect.is_partitioned(table):
                    return LakeflowPartitionedStreamReader(self.options, schema, self.lakeflow_connect)
            return super().streamReader(schema)

        def simpleStreamReader(self, schema: StructType):
            return LakeflowStreamReader(self.options, schema, self.lakeflow_connect)


    spark.dataSource.register(LakeflowSource)
